# Tam Select settings. Generated by `bin/rails generate tam_select:install`.
Rails.application.configure do
  # Render every select as a Tam Select: Simple Form's `f.input :x, collection:`
  # and `as: :select`, and Rails' select_tag, f.select, collection_select and
  # grouped_collection_select. Single selects get a blank option so they can be
  # cleared. Opt a field out with `data: { tam_select: false }`.
  config.tam_select.default_select = true
end
